        s6: "\u062E\u0635\u0648\u0645\u0627\u062A \u0645\u0639\u062F\u0627\u062A \u0627\u0644\u0645\u064A\u0627\u0647",
        s7: "\u062A\u062E\u0641\u064A\u0636\u0627\u062A AQUAVO",
        s8: "\u0623\u0633\u0639\u0627\u0631 \u0645\u062E\u0641\u0636\u0629",
