        s11: "\u062E\u0635\u0645 \u064A\u0635\u0644 \u0625\u0644\u0649",
        s12: "\u0645\u062D\u062F\u0648\u062F\u0629",
        s13: "\u0639\u0631\u0648\u0636 \u0644\u0641\u062A\u0631\u0629",
        s14: "\u0644\u0627 \u062A\u0648\u062C\u062F \u0639\u0631\u0648\u0636 \u062D\u0627\u0644\u064A\u0627\u064B",
        s15: "\u062A\u0627\u0628\u0639\u0646\u0627 \u0639\u0644\u0649 \u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u062A\u0648\u0627\u0635\u0644 \u0627\u0644\u0627\u062C\u062A\u0645\u0627\u0639\u064A \u0644\u0644\u062D\u0635\u0648\u0644 \u0639\u0644\u0649 \u0622\u062E\u0631 \u0627\u0644\u0639\u0631\u0648\u0636 \u0648\u0627\u0644\u062E\u0635\u0648\u0645\u0627\u062A",
        s16: "\u062A\u0635\u0641\u062D \u062C\u0645\u064A\u0639 \u0627\u0644\u0645\u0646\u062A\u062C\u0627\u062A",
        s17: "\u0627\u0644\u0645\u0646\u062A\u062C\u0627\u062A \u0627\u0644\u0645\u062E\u0641\u0636\u0629 (",
        s18: "\u062C\u062F\u064A\u062F",
        s19: "\u0642\u0631\u064A\u0628\u0627\u064B \u062C\u062F\u0627\u064B",
        s20: "\u0623\u0636\u0641 \u0644\u0644\u0633\u0644\u0629",
        s21: "\u0644\u0627 \u062A\u0641\u0648\u062A \u0639\u0631\u0648\u0636\u0646\u0627 \u0627\u0644\u0642\u0627\u062F\u0645\u0629!",
        s22: "\u0627\u0634\u062A\u0631\u0643 \u0641\u064A \u0646\u0634\u0631\u062A\u0646\u0627 \u0627\u0644\u0628\u0631\u064A\u062F\u064A\u0629 \u0648\u0627\u062D\u0635\u0644 \u0639\u0644\u0649 \u0625\u0634\u0639\u0627\u0631\u0627\u062A \u0641\u0648\u0631\u064A\u0629 \u0639\u0646\u062F \u0625\u0636\u0627\u0641\u0629 \u0639\u0631\u0648\u0636 \u062C\u062F\u064A\u062F\u0629",
        s23: "\u0634\u0643\u0631\u0627\u064B \u0644\u0643!",
        s24: "\u062A\u0645 \u0627\u0644\u0627\u0634\u062A\u0631\u0627\u0643 \u0628\u0646\u062C\u0627\u062D \u0641\u064A \u0627\u0644\u0646\u0634\u0631\u0629 \u0627\u0644\u0628\u0631\u064A\u062F\u064A\u0629",
        s25: "\u062E\u0637\u0623",
        s26: "\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u0627\u0634\u062A\u0631\u0627\u0643",
        s27: "\u0628\u0631\u064A\u062F\u0643 \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A",
