        s8: "\u0628\u063A\u062F\u0627\u062F \u0648\u0628\u0627\u0642\u064A \u0627\u0644\u0645\u062D\u0627\u0641\u0638\u0627\u062A",
        s9: "\u0627\u0644\u062A\u0648\u0635\u064A\u0644 \u0644\u0643\u0644 \u0627\u0644\u0639\u0631\u0627\u0642",
        s10: "\u062A\u0648\u0635\u064A\u0644 AQUAVO \u0644\u0643\u0644 \u0627\u0644\u0639\u0631\u0627\u0642 \u062E\u0644\u0627\u0644 24 \u0633\u0627\u0639\u0629 \u0628\u0623\u062C\u0631\u0629 \u062B\u0627\u0628\u062A\u0629 5,000 \u062F.\u0639\u060C \u0645\u0639 \u0627\u0644\u062F\u0641\u0639 \u0639\u0646\u062F \u0627\u0644\u0627\u0633\u062A\u0644\u0627\u0645 \u0623\u0648 \u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A\u0627\u064B.",
        s11: "\u0648\u0639\u062F \u062A\u0648\u0635\u064A\u0644 \u0648\u0627\u0636\u062D",
        s12: "\u062A\u0648\u0635\u064A\u0644 \u0644\u0643\u0644 \u0627\u0644\u0639\u0631\u0627\u0642 \u062E\u0644\u0627\u0644 24 \u0633\u0627\u0639\u0629",
        s13: "\u0623\u062C\u0631\u0629 \u0627\u0644\u062A\u0648\u0635\u064A\u0644 5,000 \u062F.\u0639\u060C \u0648\u062A\u06AF\u062F\u0631 \u062A\u062E\u062A\u0627\u0631 \u0627\u0644\u062F\u0641\u0639 \u0639\u0646\u062F \u0627\u0644\u0627\u0633\u062A\u0644\u0627\u0645 \u0623\u0648 \u0627\u0644\u062F\u0641\u0639 \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A \u0623\u062B\u0646\u0627\u0621 \u0625\u0643\u0645\u0627\u0644 \u0627\u0644\u0637\u0644\u0628. \u062A\u0634\u0648\u0641 \u0627\u0644\u0645\u0628\u0644\u063A \u0643\u0627\u0645\u0644\u0627\u064B \u0642\u0628\u0644 \u0627\u0644\u062A\u0623\u0643\u064A\u062F.",
        s14: "\u0642\u0628\u0644 \u0645\u0627 \u064A\u0637\u0644\u0639 \u0627\u0644\u0637\u0644\u0628",
        s15: "\u0646\u0631\u0627\u062C\u0639 \u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0637\u0644\u0628 \u0648\u0627\u0644\u0639\u0646\u0648\u0627\u0646. \u0625\u0630\u0627 \u0639\u0646\u062F\u0643 \u0645\u0644\u0627\u062D\u0638\u0629 \u0639\u0646 \u0627\u0644\u0648\u0635\u0648\u0644 \u0623\u0648 \u0627\u0644\u0642\u0637\u0639\u0629 \u0627\u0644\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0643\u0633\u0631\u060C \u0627\u0643\u062A\u0628\u0647\u0627 \u0628\u062D\u0642\u0644 \u0627\u0644\u0645\u0644\u0627\u062D\u0638\u0627\u062A \u062D\u062A\u0649 \u062A\u0628\u0642\u0649 \u0645\u0631\u062A\u0628\u0637\u0629 \u0628\u0627\u0644\u0637\u0644\u0628.",
        s16: "\u062A\u062A\u0628\u0639 \u0637\u0644\u0628\u0643",
        s17: "\u0627\u0633\u0623\u0644 \u0639\u0646 \u0627\u0644\u062A\u0648\u0635\u064A\u0644",
        s18: "24 \u0633\u0627\u0639\u0629",
