        s1: "\u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0627\u0644\u0627\u0633\u062A\u062B\u0645\u0627\u0631",
        s2: "\u0645\u0639\u0644\u0648\u0645\u0627\u062A AQUAVO \u0627\u0644\u0627\u0633\u062A\u062B\u0645\u0627\u0631\u064A\u0629 \u063A\u064A\u0631 \u0645\u0646\u0634\u0648\u0631\u0629 \u0644\u0644\u0639\u0627\u0645\u0629 \u062D\u0627\u0644\u064A\u0627\u064B. \u0623\u064A \u0623\u0631\u0642\u0627\u0645 \u0623\u0648 \u062A\u0648\u0642\u0639\u0627\u062A \u062A\u062D\u062A\u0627\u062C \u0628\u064A\u0627\u0646\u0627\u062A \u0645\u0627\u0644\u064A\u0629 \u0645\u062F\u0642\u0642\u0629 \u0648\u0645\u0648\u0627\u0641\u0642\u0629 \u0627\u0644\u0645\u0627\u0644\u0643.",
