        s6: "\u0627\u0644\u0639\u0633\u0631\u0629",
        s7: "\u0627\u0644\u062D\u0631\u0627\u0631\u0629",
        s8: "\u0627\u0644\u0645\u0644\u0648\u062D\u0629",
